class Solution {
    private int m;
    private List<Integer> diffs = new ArrayList<>();
    private int minLen;
    private int bestMask;

    private boolean isValid(int mask) {
        for (int d : diffs) {
            if ((mask & d) == 0) return false;
        }
        return true;
    }

    private void dfs(int idx, int currMask, int length, boolean prevZero) {
        if (length >= minLen) return;
        if (idx == m) {
            if (isValid(currMask)) {
                minLen = length;
                bestMask = currMask;
            }
            return;
        }
        dfs(idx + 1, currMask | (1 << (m - 1 - idx)), length + 1, false);
        dfs(idx + 1, currMask, length + (prevZero ? 0 : 1), true);
    }

    public String minAbbreviation(String target, String[] dictionary) {
        m = target.length();
        diffs.clear();
        for (String w : dictionary) {
            if (w.length() != m) continue;
            int mask = 0;
            for (int i = 0; i < m; i++) {
                if (target.charAt(i) != w.charAt(i)) {
                    mask |= (1 << (m - 1 - i));
                }
            }
            diffs.add(mask);
        }

        if (diffs.isEmpty()) return String.valueOf(m);

        minLen = m;
        bestMask = (1 << m) - 1;
        dfs(0, 0, 0, false);

        StringBuilder sb = new StringBuilder();
        int zeroCount = 0;
        for (int i = 0; i < m; i++) {
            if (((bestMask >> (m - 1 - i)) & 1) == 1) {
                if (zeroCount > 0) {
                    sb.append(zeroCount);
                    zeroCount = 0;
                }
                sb.append(target.charAt(i));
            } else {
                zeroCount++;
            }
        }
        if (zeroCount > 0) sb.append(zeroCount);
        return sb.toString();
    }
}

var minAbbreviation = function(target, dictionary) {
    const m = target.length;
    const diffs = [];
    for (const w of dictionary) {
        if (w.length !== m) continue;
        let mask = 0;
        for (let i = 0; i < m; i++) {
            if (target[i] !== w[i]) {
                mask |= (1 << (m - 1 - i));
            }
        }
        diffs.push(mask);
    }

    if (diffs.length === 0) return String(m);

    let minLen = m;
    let bestMask = (1 << m) - 1;

    function isValid(mask) {
        for (let i = 0; i < diffs.length; i++) {
            if ((mask & diffs[i]) === 0) return false;
        }
        return true;
    }

    function dfs(idx, currMask, length, prevZero) {
        if (length >= minLen) return;
        if (idx === m) {
            if (isValid(currMask)) {
                minLen = length;
                bestMask = currMask;
            }
            return;
        }
        dfs(idx + 1, currMask | (1 << (m - 1 - idx)), length + 1, false);
        dfs(idx + 1, currMask, length + (prevZero ? 0 : 1), true);
    }

    dfs(0, 0, 0, false);

    let res = "";
    let zeroCount = 0;
    for (let i = 0; i < m; i++) {
        if ((bestMask >> (m - 1 - i)) & 1) {
            if (zeroCount > 0) {
                res += zeroCount;
                zeroCount = 0;
            }
            res += target[i];
        } else {
            zeroCount++;
        }
    }
    if (zeroCount > 0) res += zeroCount;
    return res;
